    fn merge_view(&self, context: &mut ViewContext<Self>) -> View {
        let (Page::Merge, Some(state)) = (self.page, &self.merge) else {
            return View::empty();
        };
        // 帯の中身が変わったら、幅に合わせ直す（幅が変わったときは帯が自分で合わせ直す）。
        let bar = self.merge_bar.clone();
        let key = format!(
            "{}|{}|{}|{}|{:?}|{}",
            state.conflicts(),
            state.selected,
            state.separate,
            state.dirty(),
            state
                .sides
                .as_ref()
                .map(|s| s.as_ref().map(|(_, _, b)| b.is_some()).ok()),
            state.note
        );
        context.use_effect("merge-bar", key, move || {
            let _ = bar.request_native_element(|result| {
                if let Ok(element) = result {
                    crate::merge::fit_bar(&element);
                }
            });
            None
        });
        MERGE_UNDO.with(|u| u.set((state.can_undo(), state.can_redo())));
        let view = crate::merge::view(
            state,
            crate::merge::Callbacks {
                result_box: &self.merge_result_box,
                chosen: &self.merge_chosen,
                button: Box::new(|key| context.callback(move |()| Message::MergeButton(key))),
                pick: Box::new(|key: String| {
                    context.callback(move |()| Message::MergePick(key.clone()))
                }),
                result: context.callback(Message::MergeResult),
                base: context.callback(Message::MergeBase),
                option: context.callback(Message::Command),
                bar: &self.merge_bar,
            },
        );
        // Working Copy に埋め込むなら右の列だけ（別の窓なら全体）。
        let embedded = self.merge_embedded();
        Border::new()
            .background(Brush::Solid(crate::palette::background()))
            .grid_column(if embedded { 2 } else { 1 })
            .grid_column_span(if embedded { 1 } else { 2 })
            .content(view)
    }

    /// マージエディタを Working Copy の右の列に埋め込んで出している（別の窓に出していない）。
    fn merge_embedded(&self) -> bool {
        self.page == Page::Merge && self.merge.as_ref().is_some_and(|m| !m.separate)
    }

